function once(fn) {
  let called = false;
  let result;
  return function (...args) {
    if (!called) {
      called = true;
      result = fn.apply(this, args);
    }
    return result;
  };
}

const kakade = {
  name: 'Kakade',
  greet(times) { return `${this.name} greeted ${times}`; },
};

const greetOnce = once(kakade.greet);
console.log(greetOnce.call(kakade, 1));
console.log(greetOnce.call({ name: 'Asha' }, 2));

